import { NextRequest, NextResponse } from 'next/server';
import { createAdminClient } from '@/lib/supabase/server';
import { generatePrivateKey, hashPrivateKey } from '@/lib/auth/private-key';
import { cookies } from 'next/headers';

/**
 * POST /api/auth/signup
 * Handles Post-OAuth signup logic:
 * 1. Verifies the user is authenticated (via session) OR validates an OAuth token if provided (simpler to rely on session)
 * 2. Generates a private key if one doesn't exist
 * 3. Returns the key
 * 
 * Note: The prompt requested dealing with "oauth_token". 
 * In a Next.js App Router + Supabase Auth context, usually the client handles OAuth redirect, 
 * then the server session is established. 
 * We will check for an active session to verify identity.
 */
export async function POST(req: NextRequest) {
    try {
        const body = await req.json().catch(() => ({}));

        // We can get the user from the Supabase session
        const supabaseAdmin = createAdminClient();

        /* 
           If the client sends an 'oauth_token', we could verify it, but it's cleaner 
           to rely on the session cookie if the user just logged in.
           However, let's look at the request body usage.
        */

        // Get current user from session
        const cookieStore = cookies();
        const token = cookieStore.get('sb-access-token')?.value ||
            cookieStore.get('sb-localhost-auth-token')?.value; // Adjust depending on cookie name config

        // Using getUser() which validates the auth header or cookie
        const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);

        if (userError || !user) {
            return NextResponse.json(
                { error: 'Unauthorized. Please sign in with Google or GitHub first.' },
                { status: 401 }
            );
        }

        // Check if user already has a private key
        const { data: existingKey } = await supabaseAdmin
            .from('private_key_hash')
            .select('id')
            .eq('user_id', user.id)
            .single();

        if (existingKey) {
            return NextResponse.json(
                { error: 'Private key already exists for this account.' },
                { status: 409 }
            );
        }

        // Generate and hash private key
        const privateKey = generatePrivateKey();
        const keyHash = await hashPrivateKey(privateKey);

        // Store hash in private_key_hash table
        const { error: insertError } = await supabaseAdmin
            .from('private_key_hash')
            .insert({
                user_id: user.id,
                key_hash: keyHash,
                is_active: true
            });

        if (insertError) {
            console.error('Key storage error:', insertError);
            return NextResponse.json(
                { error: 'Failed to generate security key.' },
                { status: 500 }
            );
        }

        // Also ensure profile exists (optional, depending on if trigger does it)
        // We'll trust the trigger or previous logic, but logging success is good.

        // Return the UNHASHED key - ONE TIME ONLY
        return NextResponse.json({
            success: true,
            private_key: privateKey,
            user: {
                id: user.id,
                email: user.email,
                name: user.user_metadata?.full_name || user.user_metadata?.name || '',
            },
            message: "IMPORTANT: Save this key securely. You'll need it for public device logins."
        });

    } catch (error) {
        console.error('Signup/KeyGen error:', error);
        return NextResponse.json(
            { error: 'Internal server error' },
            { status: 500 }
        );
    }
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { SignupForm } from '@/components/auth/signup-form';
import { PrivateKeyModal } from '@/components/auth/private-key-modal'; // Assuming file name
import { useAuth } from '@/hooks/useAuth';
import { Loader2 } from 'lucide-react';
import { toast } from 'sonner';

export default function SignupPage() {
  const router = useRouter();
  const { user, loading } = useAuth();
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedKey, setGeneratedKey] = useState<string | null>(null);

  // If user lands here AND is logged in (after OAuth callback), preserve to generate key
  useEffect(() => {
    async function checkAndGenerateKey() {
      if (!loading && user) {
        // User is logged in.
        // Call API to generate key if not exists
        try {
          setIsGenerating(true);
          const res = await fetch('/api/auth/signup', {
            method: 'POST',
          });
          
          if (res.status === 409) {
            // Already has key
            // Simply redirect to home
            router.replace('/playground');
            return;
          }

          const data = await res.json();
          if (data.success && data.private_key) {
            setGeneratedKey(data.private_key);
          } else if (data.error) {
            // Might be error or just 'already exists'
            // console.error(data.error);
          }
        } catch (e) {
          console.error(e);
        } finally {
          setIsGenerating(false);
        }
      }
    }

    if (user && !loading && !generatedKey) {
      checkAndGenerateKey();
    }
  }, [user, loading, router, generatedKey]);

  const handleKeyConfirmed = () => {
     router.push('/playground');
  };

  if (loading || isGenerating) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-[#F29F67]" />
      </div>
    );
  }

  // If we have a key, show modal
  if (generatedKey) {
    return (
      <div className="min-h-screen bg-black/90">
        <PrivateKeyModal 
          privateKey={generatedKey} 
          onClose={handleKeyConfirmed}
        />
      </div>
    );
  }

  // If logged in but no key generated (implied already had one or error), we likely redirected above.
  // But if just sitting here:
  if (user) {
    return null; // or loader
  }

  // Standard Signup View
  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="space-y-6">
          <div className="text-center space-y-2">
            <h1 className="text-3xl font-bold">Create Account</h1>
            <p className="text-muted-foreground">
              Join Syntactic and start coding
            </p>
          </div>

          <div className="p-6 border rounded-lg bg-card">
            <SignupForm />
          </div>
        </div>
      </div>
    </div>
  );
}

import { createClient } from '@/lib/supabase/server';
import { notFound } from 'next/navigation';
import Link from 'next/link';
import { formatDistanceToNow } from 'date-fns';
import { ArrowLeft } from 'lucide-react';
import { MDXContent } from '@/components/mdx/mdx-content';
import { ReadingProgress } from '@/components/post/reading-progress';
import { TableOfContents } from '@/components/post/table-of-contents';
import { CommentList } from '@/components/comments/comment-list';

interface PostPageProps {
  params: {
    slug: string;
  };
}

export default async function PostPage({ params }: PostPageProps) {
  const supabase = await createClient();
  
  // Fetch post by slug
  const { data: post, error } = await supabase
    .from('posts')
    .select(`
      *,
      profiles:author_id (
        username,
        display_name,
        avatar_url,
        bio
      )
    `)
    .eq('slug', params.slug)
    .eq('published', true)
    .single();

  if (error || !post) {
    notFound();
  }

  // Increment view count
  await supabase
    .from('posts')
    .update({ view_count: (post.view_count || 0) + 1 })
    .eq('id', post.id);

  return (
    <>
      <ReadingProgress />
      
      <div className="min-h-screen bg-[#F5F5F7] dark:bg-gray-900 pt-20">
        {/* Header */}
        <div className="border-b-2 border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-900">
          <div className="max-w-7xl mx-auto px-4 py-4">
            <Link 
              href="/blog" 
              className="inline-flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400 hover:text-[#F29F67] transition-colors font-medium"
            >
              <ArrowLeft className="w-4 h-4" />
              Back to Blog
            </Link>
          </div>
        </div>

        {/* Cover Image */}
        {post.cover_image && (
          <div className="w-full h-64 md:h-96 overflow-hidden border-b-2 border-gray-300 dark:border-gray-700">
            <img
              src={post.cover_image}
              alt={post.title}
              className="w-full h-full object-cover"
            />
          </div>
        )}

        {/* Content */}
        <div className="max-w-7xl mx-auto px-4 py-12">
          <div className="grid grid-cols-1 lg:grid-cols-[1fr_250px] gap-12">
            {/* Main Content */}
            <article className="min-w-0">
              {/* Title */}
              <h1 className="text-4xl md:text-5xl font-bold mb-6 text-[#1E1E2C] dark:text-white">
                {post.title}
              </h1>

              {/* Metadata */}
              <div className="flex items-center gap-4 mb-8 pb-8 border-b-2 border-gray-300 dark:border-gray-700">
                <div className="flex items-center gap-3">
                  {post.profiles?.avatar_url ? (
                    <img
                      src={post.profiles.avatar_url}
                      alt={post.profiles.display_name || post.profiles.username}
                      className="w-12 h-12 rounded-full border-2 border-[#F29F67]"
                    />
                  ) : (
                    <div className="w-12 h-12 rounded-full bg-[#F29F67] flex items-center justify-center text-[#1E1E2C] font-bold text-lg border-2 border-[#F29F67]">
                      {post.profiles?.username?.charAt(0).toUpperCase()}
                    </div>
                  )}
                  <div>
                    <Link 
                      href={`/profile/${post.profiles?.username}`}
                      className="font-medium text-[#1E1E2C] dark:text-white hover:text-[#F29F67] transition-colors"
                    >
                      {post.profiles?.display_name || post.profiles?.username}
                    </Link>
                    <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                      <span>
                        {post.published_at && formatDistanceToNow(new Date(post.published_at), { addSuffix: true })}
                      </span>
                      {post.reading_time && (
                        <>
                          <span>ΓÇó</span>
                          <span>{post.reading_time} min read</span>
                        </>
                      )}
                      <span>ΓÇó</span>
                      <span>{post.view_count || 0} views</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* Tags */}
              {post.tags && post.tags.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-8">
                  {post.tags.map((tag: string) => (
                    <span
                      key={tag}
                      className="px-3 py-1 bg-[#F29F67]/10 border border-[#F29F67]/30 text-[#F29F67] text-sm rounded-full font-medium"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              )}

              {/* MDX Content */}
              <div className="prose prose-lg dark:prose-invert max-w-none mb-16">
                <MDXContent source={post.content} />
              </div>


              {/* Comments Section */}
              <div className="mt-16 pt-16 border-t-2 border-gray-300 dark:border-gray-700">
                <CommentList postId={post.id} />
              </div>
            </article>

            {/* Sidebar - Table of Contents */}
            <aside className="hidden lg:block">
              <TableOfContents content={post.content} />
            </aside>
          </div>
        </div>
      </div>
    </>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import { supabase } from '@/lib/supabase/client';
import { Profile } from '@/types/database';
import { Button } from '@/components/ui/button';
import { User, Mail, Globe, Github, Twitter, Calendar, Edit } from 'lucide-react';
import Link from 'next/link';
import { useAuth } from '@/hooks/useAuth';

export default function ProfilePage() {
  const params = useParams();
  const username = params.username as string;
  const { user: currentUser } = useAuth();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [postsCount, setPostsCount] = useState(0);
  const [codeFilesCount, setCodeFilesCount] = useState(0);
  const [posts, setPosts] = useState<any[]>([]);
  const [codeFiles, setCodeFiles] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'posts' | 'code' | 'activity'>('posts');

  useEffect(() => {
    fetchProfile();
  }, [username]);

  async function fetchProfile() {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('username', username)
        .single();

      if (error) {
        if (error.code === 'PGRST116') {
          setNotFound(true);
        }
        throw error;
      }

      setProfile(data);
      
      // Fetch posts count and data
      const { count: postsCount, data: postsData } = await supabase
        .from('posts')
        .select('*', { count: 'exact' })
        .eq('author_id', data.id)
        .eq('published', true)
        .order('published_at', { ascending: false })
        .limit(10);
      
      setPostsCount(postsCount || 0);
      setPosts(postsData || []);
      
      // Fetch code files count and data
      // Show all files if viewing own profile, only public files for others
      const { data: { user: currentUser } } = await supabase.auth.getUser();
      const isOwnProfile = currentUser?.id === data.id;
      
      let filesQuery = supabase
        .from('code_files')
        .select('*', { count: 'exact' })
        .eq('user_id', data.id)
        .order('created_at', { ascending: false })
        .limit(10);
      
      // Only filter by is_public if viewing someone else's profile
      if (!isOwnProfile) {
        filesQuery = filesQuery.eq('is_public', true);
      }
      
      const { count: filesCount, data: filesData } = await filesQuery;
      
      setCodeFilesCount(filesCount || 0);
      setCodeFiles(filesData || []);
    } catch (error) {
      console.error('Error fetching profile:', error);
    } finally {
      setLoading(false);
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Loading profile...</p>
        </div>
      </div>
    );
  }

  if (notFound || !profile) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center space-y-4">
          <h1 className="text-4xl font-bold">404</h1>
          <p className="text-xl text-muted-foreground">User not found</p>
          <Link href="/">
            <Button>Go Home</Button>
          </Link>
        </div>
      </div>
    );
  }

  const isOwnProfile = currentUser?.id === profile.id;

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pt-24">
      <div className="max-w-4xl mx-auto p-6 space-y-6">
        {/* Profile Header */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-8">
          <div className="flex items-start justify-between">
            <div className="flex items-start gap-6">
              {/* Avatar */}
              <div className="w-24 h-24 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white text-3xl font-bold">
                {profile.avatar_url ? (
                  <img
                    src={profile.avatar_url}
                    alt={profile.username}
                    className="w-full h-full rounded-full object-cover"
                  />
                ) : (
                  profile.username.charAt(0).toUpperCase()
                )}
              </div>

              {/* Info */}
              <div className="space-y-3">
                <div>
                  <h1 className="text-3xl font-bold">
                    {profile.display_name || profile.username}
                  </h1>
                  <p className="text-muted-foreground">@{profile.username}</p>
                </div>

                {profile.bio && (
                  <p className="text-gray-700 dark:text-gray-300 max-w-2xl">
                    {profile.bio}
                  </p>
                )}

                {/* Links */}
                <div className="flex flex-wrap gap-4 text-sm">
                  {profile.website_url && (
                    <a
                      href={profile.website_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-1 text-blue-600 hover:underline"
                    >
                      <Globe className="w-4 h-4" />
                      Website
                    </a>
                  )}
                  {profile.github_username && (
                    <a
                      href={`https://github.com/${profile.github_username}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-1 text-gray-700 dark:text-gray-300 hover:underline"
                    >
                      <Github className="w-4 h-4" />
                      GitHub
                    </a>
                  )}
                  {profile.twitter_username && (
                    <a
                      href={`https://twitter.com/${profile.twitter_username}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-1 text-blue-400 hover:underline"
                    >
                      <Twitter className="w-4 h-4" />
                      Twitter
                    </a>
                  )}
                </div>

                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Calendar className="w-4 h-4" />
                  Joined {new Date(profile.created_at).toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
                </div>
              </div>
            </div>

            {/* Edit Button */}
            {isOwnProfile && (
              <Link href="/settings">
                <Button variant="outline">
                  <Edit className="w-4 h-4 mr-2" />
                  Edit Profile
                </Button>
              </Link>
            )}
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-6 text-center">
            <div className="text-3xl font-bold text-blue-600">{postsCount}</div>
            <div className="text-sm text-muted-foreground">Posts</div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-6 text-center">
            <div className="text-3xl font-bold text-green-600">{codeFilesCount}</div>
            <div className="text-sm text-muted-foreground">Code Files</div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-6 text-center">
            <div className="text-3xl font-bold text-purple-600">0</div>
            <div className="text-sm text-muted-foreground">Followers</div>
          </div>
        </div>

        {/* Content Tabs */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-6">
          <div className="border-b border-gray-200 dark:border-gray-700 mb-6">
            <div className="flex gap-6">
              <button 
                onClick={() => setActiveTab('posts')}
                className={`pb-3 border-b-2 font-medium ${
                  activeTab === 'posts' 
                    ? 'border-blue-600 text-blue-600' 
                    : 'border-transparent text-muted-foreground hover:text-foreground'
                }`}
              >
                Posts ({postsCount})
              </button>
              <button 
                onClick={() => setActiveTab('code')}
                className={`pb-3 border-b-2 font-medium ${
                  activeTab === 'code' 
                    ? 'border-blue-600 text-blue-600' 
                    : 'border-transparent text-muted-foreground hover:text-foreground'
                }`}
              >
                Code Files ({codeFilesCount})
              </button>
              <button 
                onClick={() => setActiveTab('activity')}
                className={`pb-3 border-b-2 font-medium ${
                  activeTab === 'activity' 
                    ? 'border-blue-600 text-blue-600' 
                    : 'border-transparent text-muted-foreground hover:text-foreground'
                }`}
              >
                Activity
              </button>
            </div>
          </div>

          {/* Posts Tab */}
          {activeTab === 'posts' && (
            <div className="space-y-4">
              {posts.length === 0 ? (
                <div className="text-center py-12 text-muted-foreground">
                  <p>No posts yet</p>
                </div>
              ) : (
                posts.map((post) => (
                  <Link 
                    key={post.id} 
                    href={`/post/${post.slug}`}
                    className="block p-4 border border-gray-200 dark:border-gray-700 rounded-lg hover:border-blue-500 transition-colors"
                  >
                    <h3 className="font-semibold text-lg mb-1">{post.title}</h3>
                    {post.excerpt && (
                      <p className="text-sm text-muted-foreground line-clamp-2 mb-2">
                        {post.excerpt}
                      </p>
                    )}
                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
                      <span>{new Date(post.published_at).toLocaleDateString()}</span>
                      {post.reading_time && <span>{post.reading_time} min read</span>}
                      <span>{post.view_count || 0} views</span>
                    </div>
                  </Link>
                ))
              )}
            </div>
          )}

          {/* Code Files Tab */}
          {activeTab === 'code' && (
            <div className="space-y-4">
              {codeFiles.length === 0 ? (
                <div className="text-center py-12 text-muted-foreground">
                  <p>No public code files yet</p>
                </div>
              ) : (
                codeFiles.map((file) => (
                  <div 
                    key={file.id}
                    className="p-4 border border-gray-200 dark:border-gray-700 rounded-lg"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <h3 className="font-semibold mb-1">{file.filename}</h3>
                        {file.description && (
                          <p className="text-sm text-muted-foreground mb-2">
                            {file.description}
                          </p>
                        )}
                        <div className="flex items-center gap-3 text-xs text-muted-foreground">
                          <span className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded">
                            {file.language}
                          </span>
                          <span>{new Date(file.created_at).toLocaleDateString()}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

          {/* Activity Tab */}
          {activeTab === 'activity' && (
            <div className="text-center py-12 text-muted-foreground">
              <p>Activity feed coming soon</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { createClient } from '@/lib/supabase/server';
import Link from 'next/link';
import { formatDistanceToNow } from 'date-fns';
import { Search } from 'lucide-react';

interface SearchPageProps {
  searchParams: {
    q?: string;
  };
}

interface SearchPost {
  id: string;
  slug: string;
  title: string;
  excerpt?: string;
  published_at?: string;
  profiles?: {
    username?: string;
    display_name?: string;
    avatar_url?: string;
  };
}

export default async function SearchPage({ searchParams }: SearchPageProps) {
  const query = searchParams.q || '';
  const supabase = await createClient();

  let posts: SearchPost[] = [];
  
  if (query) {
    const { data } = await supabase.rpc('search_posts', { search_query: query });
    
    // Fetch author details for the results (since RPC returns raw posts)
    if (data && data.length > 0) {
      const postIds = data.map((p: { id: string }) => p.id);
      const { data: postsWithAuthors } = await supabase
        .from('posts')
        .select(`
          *,
          profiles:author_id (
            username,
            display_name,
            avatar_url
          )
        `)
        .in('id', postIds)
        .eq('published', true);
        
      if (postsWithAuthors) {
        posts = postsWithAuthors as unknown as SearchPost[];
      }
    }
  }

  return (
    <div className="min-h-screen bg-white dark:bg-gray-900 py-12">
      <div className="max-w-4xl mx-auto px-4">
        <div className="mb-8">
          <h1 className="text-3xl font-bold mb-2">Search Results</h1>
          <p className="text-muted-foreground">
            {query ? `Showing results for "${query}"` : 'Enter a search term to find posts'}
          </p>
        </div>

        <div className="space-y-6">
          {posts.length === 0 ? (
            <div className="text-center py-12 border rounded-lg border-dashed border-gray-200 dark:border-gray-800">
              <Search className="w-12 h-12 mx-auto text-muted-foreground mb-4 opacity-50" />
              <p className="text-muted-foreground">No posts found matching your query</p>
            </div>
          ) : (
            posts.map((post) => (
              <Link 
                key={post.id} 
                href={`/post/${post.slug}`}
                className="block p-6 border border-gray-200 dark:border-gray-800 rounded-lg hover:border-blue-500 transition-colors bg-white dark:bg-gray-950"
              >
                <h2 className="text-xl font-bold mb-2">{post.title}</h2>
                <p className="text-muted-foreground mb-4 line-clamp-2">{post.excerpt}</p>
                <div className="flex items-center gap-4 text-sm text-muted-foreground">
                  <div className="flex items-center gap-2">
                    {post.profiles?.avatar_url && (
                      <img src={post.profiles.avatar_url} className="w-5 h-5 rounded-full" alt="" />
                    )}
                    <span>{post.profiles?.display_name || post.profiles?.username}</span>
                  </div>
                  {post.published_at && (
                    <span>{formatDistanceToNow(new Date(post.published_at), { addSuffix: true })}</span>
                  )}
                </div>
              </Link>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/hooks/useAuth';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { supabase } from '@/lib/supabase/client';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { User, Settings as SettingsIcon, LogOut } from 'lucide-react';
import { AvatarUpload } from '@/components/profile/avatar-upload';

export default function SettingsPage() {
  const router = useRouter();
  const { user, profile, loading: authLoading, signOut } = useAuth();
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  // Profile form
  const [profileForm, setProfileForm] = useState({
    display_name: '',
    bio: '',
    website_url: '',
    github_username: '',
    twitter_username: '',
  });

  // Preferences form
  const [preferencesForm, setPreferencesForm] = useState({
    editor_theme: 'vs-dark',
    editor_font_size: 14,
    reading_mode: 'auto',
    email_notifications: true,
    show_line_numbers: true,
    auto_save: true,
  });

  useEffect(() => {
    if (!authLoading && !user) {
      router.push('/auth/login');
    }

    if (profile) {
      setProfileForm({
        display_name: profile.display_name || '',
        bio: profile.bio || '',
        website_url: profile.website_url || '',
        github_username: profile.github_username || '',
        twitter_username: profile.twitter_username || '',
      });

      // Fetch preferences
      fetchPreferences();
    }
  }, [user, profile, authLoading]);

  async function fetchPreferences() {
    if (!user) return;

    try {
      const { data, error } = await supabase
        .from('user_preferences')
        .select('*')
        .eq('user_id', user.id)
        .single();

      if (error) throw error;

      if (data) {
        setPreferencesForm({
          editor_theme: data.editor_theme,
          editor_font_size: data.editor_font_size,
          reading_mode: data.reading_mode,
          email_notifications: data.email_notifications,
          show_line_numbers: data.show_line_numbers,
          auto_save: data.auto_save,
        });
      }
    } catch (error) {
      console.error('Error fetching preferences:', error);
    }
  }

  async function handleProfileUpdate(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;

    setLoading(true);
    setMessage('');
    setError('');

    try {
      const { error } = await supabase
        .from('profiles')
        .update({
          display_name: profileForm.display_name || null,
          bio: profileForm.bio || null,
          website_url: profileForm.website_url || null,
          github_username: profileForm.github_username || null,
          twitter_username: profileForm.twitter_username || null,
        })
        .eq('id', user.id);

      if (error) throw error;

      setMessage('Profile updated successfully!');
      setTimeout(() => setMessage(''), 3000);
    } catch (err: unknown) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred');
      }
    } finally {
      setLoading(false);
    }
  }

  async function handlePreferencesUpdate(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;

    setLoading(true);
    setMessage('');
    setError('');

    try {
      const { error } = await supabase
        .from('user_preferences')
        .update(preferencesForm)
        .eq('user_id', user.id);

      if (error) throw error;

      setMessage('Preferences updated successfully!');
      setTimeout(() => setMessage(''), 3000);
    } catch (err: unknown) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred');
      }
    } finally {
      setLoading(false);
    }
  }

  async function handleSignOut() {
    await signOut();
    router.push('/');
  }

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!user) {
    return null;
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      <div className="max-w-4xl mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold">Settings</h1>
            <p className="text-muted-foreground">Manage your account and preferences</p>
          </div>
          <Button variant="outline" onClick={handleSignOut}>
            <LogOut className="w-4 h-4 mr-2" />
            Sign Out
          </Button>
        </div>

        {message && (
          <div className="p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg text-green-700 dark:text-green-400">
            {message}
          </div>
        )}

        {error && (
          <div className="p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-red-700 dark:text-red-400">
            {error}
          </div>
        )}

        <Tabs defaultValue="profile" className="space-y-6">
          <TabsList>
            <TabsTrigger value="profile">
              <User className="w-4 h-4 mr-2" />
              Profile
            </TabsTrigger>
            <TabsTrigger value="preferences">
              <SettingsIcon className="w-4 h-4 mr-2" />
              Preferences
            </TabsTrigger>
          </TabsList>

          <TabsContent value="profile">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-6">
              <div className="mb-8 flex justify-center">
                <AvatarUpload
                  url={profile?.avatar_url || null}
