'use client';

import { useState } from 'react';
import { formatDistanceToNow } from 'date-fns';
import { MessageCircle, Trash2, Reply } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { CommentForm } from './comment-form';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/lib/supabase/client';
import { toast } from 'sonner';

interface CommentItemProps {
  comment: any;
  postId: string;
  onRefresh: () => void;
  level?: number;
}

export function CommentItem({ comment, postId, onRefresh, level = 0 }: CommentItemProps) {
  const { user } = useAuth();
  const [isReplying, setIsReplying] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const isOwner = user?.id === comment.user_id;
  const hasReplies = comment.replies && comment.replies.length > 0;

  async function handleDelete() {
    if (!confirm('Are you sure you want to delete this comment?')) return;
    
    setIsDeleting(true);
    try {
      const { error } = await supabase
        .from('comments')
        .delete()
        .eq('id', comment.id);

      if (error) throw error;
      
      toast.success('Comment deleted');
      onRefresh();
    } catch (error) {
      console.error('Error deleting comment:', error);
      toast.error('Failed to delete comment');
    } finally {
      setIsDeleting(false);
    }
  }

  return (
    <div className={`space-y-4 ${level > 0 ? 'ml-8 pl-4 border-l-2 border-gray-100 dark:border-gray-800' : ''}`}>
      <div className="flex gap-4">
        {/* Avatar */}
        <div className="flex-shrink-0">
          <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white font-bold text-sm">
            {comment.profiles?.avatar_url ? (
              <img
                src={comment.profiles.avatar_url}
                alt={comment.profiles.username}
                className="w-full h-full rounded-full object-cover"
              />
            ) : (
              (comment.profiles?.username || '?').charAt(0).toUpperCase()
            )}
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 space-y-2">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="font-semibold text-sm">
                {comment.profiles?.display_name || comment.profiles?.username || 'Unknown User'}
              </span>
              <span className="text-xs text-muted-foreground">
                {formatDistanceToNow(new Date(comment.created_at), { addSuffix: true })}
              </span>
            </div>
            {isOwner && (
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6 text-muted-foreground hover:text-red-500"
                onClick={handleDelete}
                disabled={isDeleting}
              >
                <Trash2 className="w-3 h-3" />
              </Button>
            )}
          </div>

          <div className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">
            {comment.content}
          </div>

          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              className="h-auto p-0 text-muted-foreground hover:text-foreground text-xs"
              onClick={() => setIsReplying(!isReplying)}
            >
              <Reply className="w-3 h-3 mr-1" />
              Reply
            </Button>
          </div>

          {isReplying && (
            <div className="mt-4">
              <CommentForm
                postId={postId}
                parentId={comment.id}
                onCommentAdded={() => {
                  setIsReplying(false);
                  onRefresh();
                }}
                onCancel={() => setIsReplying(false)}
              />
            </div>
          )}
        </div>
      </div>

      {/* Nested Replies */}
      {hasReplies && (
        <div className="space-y-4">
          {comment.replies.map((reply: any) => (
            <CommentItem
              key={reply.id}
              comment={reply}
              postId={postId}
              onRefresh={onRefresh}
              level={level + 1}
            />
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { MessageCircle } from 'lucide-react';
import { supabase } from '@/lib/supabase/client';
import { CommentForm } from './comment-form';
import { CommentItem } from './comment-item';
import { useAuth } from '@/hooks/useAuth';
import Link from 'next/link';
import { Button } from '@/components/ui/button';

interface CommentSectionProps {
  postId: string;
}

export function CommentSection({ postId }: CommentSectionProps) {
  const { user } = useAuth();
  const [comments, setComments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchComments();
  }, [postId]);

  async function fetchComments() {
    try {
      const { data, error } = await supabase
        .from('comments')
        .select(`
          *,
          profiles (
            id,
            username,
            display_name,
            avatar_url
          )
        `)
        .eq('post_id', postId)
        .order('created_at', { ascending: true });

      if (error) throw error;

      // Organize into tree structure
      const commentTree = buildCommentTree(data || []);
      setComments(commentTree);
    } catch (error) {
      console.error('Error fetching comments:', error);
    } finally {
      setLoading(false);
    }
  }

  function buildCommentTree(flatComments: any[]) {
    const commentMap = new Map();
    const roots: any[] = [];

    // Initialize map
    flatComments.forEach(comment => {
      comment.replies = [];
      commentMap.set(comment.id, comment);
    });

    // Build tree
    flatComments.forEach(comment => {
      if (comment.parent_id) {
        const parent = commentMap.get(comment.parent_id);
        if (parent) {
          parent.replies.push(comment);
        } else {
          // Orphaned comment (parent deleted?), treat as root
          roots.push(comment);
        }
      } else {
        roots.push(comment);
      }
    });

    return roots;
  }

  return (
    <div className="space-y-8" id="comments">
      <div className="flex items-center gap-2 text-xl font-semibold">
        <MessageCircle className="w-6 h-6" />
        <h2>Comments</h2>
      </div>

      {user ? (
        <CommentForm postId={postId} onCommentAdded={fetchComments} />
      ) : (
        <div className="bg-gray-50 dark:bg-gray-800/50 p-6 rounded-lg text-center">
          <p className="text-muted-foreground mb-4">Log in to join the discussion</p>
          <Link href="/auth/login">
            <Button>Log In</Button>
          </Link>
        </div>
      )}

      <div className="space-y-8">
        {loading ? (
          <div className="text-center text-muted-foreground">Loading comments...</div>
        ) : comments.length === 0 ? (
          <div className="text-center text-muted-foreground py-8">
            No comments yet. Be the first to share your thoughts!
          </div>
        ) : (
          comments.map((comment) => (
            <CommentItem
              key={comment.id}
              comment={comment}
              postId={postId}
              onRefresh={fetchComments}
            />
          ))
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Heart } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { supabase } from '@/lib/supabase/client';
import { cn } from '@/lib/utils';
import { useAuth } from '@/hooks/useAuth';
import { toast } from 'sonner';

interface LikeButtonProps {
  postId: string;
  initialLikes?: number;
}

export function LikeButton({ postId, initialLikes = 0 }: LikeButtonProps) {
  const { user } = useAuth();
  const [liked, setLiked] = useState(false);
  const [likesCount, setLikesCount] = useState(initialLikes);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (user) {
      checkIfLiked();
    }
    fetchLikesCount();
  }, [postId, user]);

  async function checkIfLiked() {
    if (!user) return;
    
    const { data } = await supabase
      .from('post_likes')
      .select('user_id')
      .eq('post_id', postId)
      .eq('user_id', user.id)
      .single();
      
    setLiked(!!data);
  }

  async function fetchLikesCount() {
    const { count } = await supabase
      .from('post_likes')
      .select('*', { count: 'exact', head: true })
      .eq('post_id', postId);
      
    setLikesCount(count || 0);
  }

  async function handleToggleLike() {
    if (!user) {
      toast.error('Please login to like posts');
      return;
    }

    if (loading) return;
    setLoading(true);

    // Optimistic update
    const previousLiked = liked;
    const previousCount = likesCount;
    
    setLiked(!liked);
    setLikesCount(liked ? likesCount - 1 : likesCount + 1);

    try {
      if (previousLiked) {
        // Unlike
        const { error } = await supabase
          .from('post_likes')
          .delete()
          .eq('post_id', postId)
          .eq('user_id', user.id);
          
        if (error) throw error;
      } else {
        // Like
        const { error } = await supabase
          .from('post_likes')
          .insert({ post_id: postId, user_id: user.id });
          
        if (error) throw error;
      }
    } catch (error) {
      console.error('Error toggling like:', error);
      // Revert on error
      setLiked(previousLiked);
      setLikesCount(previousCount);
      toast.error('Failed to update like');
    } finally {
      setLoading(false);
    }
  }

  return (
    <Button
      variant="ghost"
      size="sm"
      onClick={handleToggleLike}
      disabled={loading}
      className={cn(
        "group flex items-center gap-2 transition-colors",
        liked ? "text-red-500 hover:text-red-600" : "text-muted-foreground hover:text-red-500"
      )}
    >
      <Heart className={cn("w-5 h-5 transition-all", liked && "fill-current scale-110")} />
      <span className="font-medium">{likesCount}</span>
    </Button>
  );
}

'use client';

import { useState } from 'react';
import { formatDistanceToNow } from 'date-fns';
import { MessageCircle, Trash2, Edit2, MoreVertical } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { Button } from '@/components/ui/button';
import { CommentForm } from './comment-form';

interface Comment {
  id: string;
  content: string;
  created_at: string;
  user_id: string;
  profiles: {
    username: string;
    display_name?: string;
    avatar_url?: string;
  };
}

interface CommentItemProps {
  comment: Comment;
  onReply?: () => void;
  onDelete?: (id: string) => void;
  onUpdate?: () => void;
  depth?: number;
}

export function CommentItem({ comment, onReply, onDelete, onUpdate, depth = 0 }: CommentItemProps) {
  const { user } = useAuth();
  const [showReplyForm, setShowReplyForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  const isOwner = user?.id === comment.user_id;
  const maxDepth = 3;

  const handleDelete = async () => {
    if (!confirm('Are you sure you want to delete this comment?')) return;
    
    try {
      const response = await fetch(`/api/comments/${comment.id}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Failed to delete comment');
      
      if (onDelete) onDelete(comment.id);
      if (onUpdate) onUpdate();
    } catch (error) {
      console.error('Error deleting comment:', error);
      alert('Failed to delete comment');
    }
  };

  return (
    <div className={`${depth > 0 ? 'ml-8 md:ml-12' : ''}`}>
      <div className="flex gap-3 group">
        {/* Avatar */}
        <div className="flex-shrink-0">
          {comment.profiles.avatar_url ? (
            <img
              src={comment.profiles.avatar_url}
              alt={comment.profiles.username}
              className="w-10 h-10 rounded-full border-2 border-[#F29F67]"
            />
          ) : (
            <div className="w-10 h-10 rounded-full bg-[#F29F67] flex items-center justify-center border-2 border-[#F29F67]">
              <span className="text-[#1E1E2C] text-sm font-bold">
                {comment.profiles.username.charAt(0).toUpperCase()}
              </span>
            </div>
          )}
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="bg-[#F5F5F7] dark:bg-gray-800 rounded-2xl p-4 border-2 border-gray-300 dark:border-gray-700">
            <div className="flex items-start justify-between mb-2">
              <div>
                <span className="font-semibold text-[#1E1E2C] dark:text-white">
                  {comment.profiles.display_name || comment.profiles.username}
                </span>
                <span className="text-sm text-gray-500 ml-2">
                  {formatDistanceToNow(new Date(comment.created_at), { addSuffix: true })}
                </span>
              </div>
              
              {isOwner && (
                <div className="relative">
                  <button
                    onClick={() => setShowMenu(!showMenu)}
                    className="p-1 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-700 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <MoreVertical className="w-4 h-4 text-gray-600 dark:text-gray-400" />
                  </button>
                  
                  {showMenu && (
                    <div className="absolute right-0 mt-1 w-32 bg-white dark:bg-gray-800 rounded-lg shadow-lg border-2 border-gray-300 dark:border-gray-700 z-10">
                      <button
                        onClick={() => {
                          setIsEditing(true);
                          setShowMenu(false);
                        }}
                        className="w-full px-3 py-2 text-left text-sm hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 rounded-t-lg"
                      >
                        <Edit2 className="w-3 h-3" />
                        Edit
                      </button>
                      <button
                        onClick={() => {
                          handleDelete();
                          setShowMenu(false);
                        }}
                        className="w-full px-3 py-2 text-left text-sm hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 text-red-600 rounded-b-lg"
                      >
                        <Trash2 className="w-3 h-3" />
                        Delete
                      </button>
                    </div>
                  )}
                </div>
              )}
            </div>
            
            <p className="text-gray-700 dark:text-gray-300 whitespace-pre-wrap break-words">
              {comment.content}
            </p>
          </div>

          {/* Actions */}
          {depth < maxDepth && (
            <div className="mt-2 flex items-center gap-4">
              <button
                onClick={() => setShowReplyForm(!showReplyForm)}
                className="text-sm text-gray-600 dark:text-gray-400 hover:text-[#F29F67] dark:hover:text-[#F29F67] flex items-center gap-1 font-medium"
              >
                <MessageCircle className="w-4 h-4" />
                Reply
              </button>
            </div>
          )}

          {/* Reply Form */}
          {showReplyForm && (
            <div className="mt-4">
              <CommentForm
                postId={comment.id}
                parentId={comment.id}
                onCommentAdded={() => {
                  setShowReplyForm(false);
                  if (onUpdate) onUpdate();
                }}
                onCancel={() => setShowReplyForm(false)}
                placeholder="Write a reply..."
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { MessageSquare, Loader2 } from 'lucide-react';
import { CommentForm } from './comment-form';
import { CommentItem } from './comment-item';

interface Comment {
  id: string;
  content: string;
  created_at: string;
  user_id: string;
  parent_id: string | null;
  profiles: {
    username: string;
    display_name?: string;
    avatar_url?: string;
  };
  replies?: Comment[];
}

interface CommentListProps {
  postId: string;
}

export function CommentList({ postId }: CommentListProps) {
  const [comments, setComments] = useState<Comment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchComments = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/comments?post_id=${postId}`);
      
      if (!response.ok) throw new Error('Failed to fetch comments');
      
      const data = await response.json();
      
      // Organize comments into threads
      const commentMap = new Map<string, Comment>();
      const rootComments: Comment[] = [];
      
      // First pass: create map of all comments
      data.forEach((comment: Comment) => {
        commentMap.set(comment.id, { ...comment, replies: [] });
      });
      
      // Second pass: organize into threads
      data.forEach((comment: Comment) => {
        const commentWithReplies = commentMap.get(comment.id)!;
        
        if (comment.parent_id) {
          const parent = commentMap.get(comment.parent_id);
          if (parent) {
            parent.replies = parent.replies || [];
            parent.replies.push(commentWithReplies);
          }
        } else {
          rootComments.push(commentWithReplies);
        }
      });
      
      setComments(rootComments);
      setError(null);
    } catch (err) {
      console.error('Error fetching comments:', err);
      setError('Failed to load comments');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchComments();
  }, [postId]);

  const renderComment = (comment: Comment, depth = 0) => (
    <div key={comment.id} className="space-y-4">
      <CommentItem
        comment={comment}
        onUpdate={fetchComments}
        onDelete={fetchComments}
        depth={depth}
      />
      {comment.replies && comment.replies.length > 0 && (
        <div className="space-y-4">
          {comment.replies.map((reply) => renderComment(reply, depth + 1))}
        </div>
      )}
    </div>
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-[#F29F67]" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-12">
        <p className="text-red-600 dark:text-red-400">{error}</p>
        <button
          onClick={fetchComments}
          className="mt-4 text-[#F29F67] hover:text-[#E08D55] font-medium"
        >
          Try again
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex items-center gap-2">
        <MessageSquare className="w-5 h-5 text-[#F29F67]" />
        <h3 className="text-2xl font-bold text-[#1E1E2C] dark:text-white">
          Comments ({comments.length})
        </h3>
      </div>

      {/* Comment Form */}
      <CommentForm postId={postId} onCommentAdded={fetchComments} />

      {/* Comments */}
      {comments.length === 0 ? (
        <div className="text-center py-12 bg-[#F5F5F7] dark:bg-gray-800 rounded-2xl border-2 border-gray-300 dark:border-gray-700">
          <MessageSquare className="w-12 h-12 mx-auto mb-3 text-gray-400" />
          <p className="text-gray-600 dark:text-gray-400">No comments yet. Be the first to comment!</p>
        </div>
      ) : (
        <div className="space-y-6">
          {comments.map((comment) => renderComment(comment))}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useRef } from 'react';
import { supabase } from '@/lib/supabase/client';
import { Button } from '@/components/ui/button';
import { Upload, X, Loader2, Image as ImageIcon } from 'lucide-react';

interface CoverImageUploadProps {
  url: string | null;
  onUpload: (url: string) => void;
  onRemove: () => void;
}

export function CoverImageUpload({ url, onUpload, onRemove }: CoverImageUploadProps) {
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  async function uploadImage(event: React.ChangeEvent<HTMLInputElement>) {
    try {
      setUploading(true);
      setError('');

      if (!event.target.files || event.target.files.length === 0) {
        return;
      }

      const file = event.target.files[0];
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random().toString(36).substring(2)}-${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;

      // Check file size (max 5MB for covers)
      if (file.size > 5 * 1024 * 1024) {
        throw new Error('Image must be smaller than 5MB.');
      }

      // Upload to Supabase Storage
      const { error: uploadError } = await supabase.storage
        .from('post-images')
        .upload(filePath, file);

      if (uploadError) {
        throw uploadError;
      }

      // Get public URL
      const { data } = supabase.storage.from('post-images').getPublicUrl(filePath);
      
      onUpload(data.publicUrl);
    } catch (error: any) {
      setError(error.message);
    } finally {
      setUploading(false);
    }
  }

  return (
    <div className="space-y-4">
      <div 
        className={`relative aspect-video rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-700 overflow-hidden flex items-center justify-center bg-gray-50 dark:bg-gray-800 ${!url ? 'cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700' : ''}`}
        onClick={() => !url && fileInputRef.current?.click()}
      >
        {url ? (
          <>
            <img
              src={url}
              alt="Cover"
              className="w-full h-full object-cover"
            />
            <div className="absolute top-2 right-2 flex gap-2">
              <Button
                variant="secondary"
                size="icon"
                className="h-8 w-8 bg-white/80 hover:bg-white text-gray-700"
                onClick={(e) => {
                  e.stopPropagation();
                  fileInputRef.current?.click();
                }}
              >
                <Upload className="w-4 h-4" />
              </Button>
              <Button
                variant="destructive"
                size="icon"
                className="h-8 w-8"
                onClick={(e) => {
                  e.stopPropagation();
                  onRemove();
                }}
              >
                <X className="w-4 h-4" />
              </Button>
            </div>
          </>
        ) : (
          <div className="flex flex-col items-center gap-2 text-muted-foreground">
            {uploading ? (
              <Loader2 className="w-8 h-8 animate-spin" />
            ) : (
              <ImageIcon className="w-8 h-8" />
            )}
            <span className="text-sm">
              {uploading ? 'Uploading...' : 'Click to upload cover image'}
            </span>
          </div>
        )}
      </div>

      <input
        type="file"
        id="cover-upload"
        accept="image/*"
        onChange={uploadImage}
        disabled={uploading}
        ref={fileInputRef}
        className="hidden"
      />

      {error && (
        <p className="text-xs text-red-500">{error}</p>
      )}
    </div>
  );
}

'use client';

import Editor, { OnMount } from '@monaco-editor/react';
import { useTheme } from 'next-themes';
import { useEffect, useState } from 'react';

interface MdxEditorProps {
  value: string;
  onChange: (value: string) => void;
}

export function MdxEditor({ value, onChange }: MdxEditorProps) {
  const { theme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const handleEditorDidMount: OnMount = (editor, monaco) => {
    // Configure editor settings
    editor.updateOptions({
      minimap: { enabled: false },
      scrollBeyondLastLine: false,
      wordWrap: 'on',
      fontSize: 14,
      fontFamily: "'Fira Code', monospace",
      lineNumbers: 'off',
      folding: false,
      lineDecorationsWidth: 0,
      lineNumbersMinChars: 0,
      renderLineHighlight: 'none',
      padding: { top: 16, bottom: 16 },
    });
  };

  if (!mounted) return null;

  return (
    <div className="h-full w-full">
      <Editor
        height="100%"
        defaultLanguage="markdown"
        value={value}
        onChange={(value) => onChange(value || '')}
        theme={theme === 'dark' ? 'vs-dark' : 'light'}
        options={{
          minimap: { enabled: false },
          wordWrap: 'on',
        }}
        onMount={handleEditorDidMount}
        loading={
          <div className="flex items-center justify-center h-full text-muted-foreground">
            Loading editor...
          </div>
        }
      />
    </div>
  );
}

'use client';

import { X, Plus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { CoverImageUpload } from './cover-image-upload';
import { TagInput } from './tag-input';
import { useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase/client';
import { toast } from 'sonner';

interface PostSettingsProps {
  isOpen: boolean;
  onClose: () => void;
  post: {
    title: string;
    slug: string;
    excerpt: string | null;
    cover_image: string | null;
    tags: string[];
    published: boolean;
    series_id?: string | null;
  };
  onUpdate: (updates: any) => void;
}

export function PostSettings({ isOpen, onClose, post, onUpdate }: PostSettingsProps) {
  const [slug, setSlug] = useState(post.slug);
  const [excerpt, setExcerpt] = useState(post.excerpt || '');
  const [series, setSeries] = useState<any[]>([]);
  const [isCreatingSeries, setIsCreatingSeries] = useState(false);
  const [newSeriesTitle, setNewSeriesTitle] = useState('');

  useEffect(() => {
    setSlug(post.slug);
    setExcerpt(post.excerpt || '');
    fetchSeries();
  }, [post]);

  async function fetchSeries() {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    const { data } = await supabase
      .from('series')
      .select('*')
      .eq('author_id', user.id)
      .order('created_at', { ascending: false });
    
    if (data) setSeries(data);
  }

  async function handleCreateSeries() {
    if (!newSeriesTitle.trim()) return;

    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    const slug = newSeriesTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');

    const { data, error } = await supabase
      .from('series')
      .insert({
        title: newSeriesTitle,
        slug,
        author_id: user.id
      })
      .select()
      .single();

    if (error) {
      toast.error('Failed to create series');
      return;
    }

    setSeries([data, ...series]);
    onUpdate({ series_id: data.id });
    setIsCreatingSeries(false);
    setNewSeriesTitle('');
    toast.success('Series created!');
  }

  if (!isOpen) return null;

  return (
    <div className="fixed inset-y-0 right-0 w-96 bg-white dark:bg-gray-900 border-l border-gray-200 dark:border-gray-800 shadow-xl z-50 overflow-y-auto transform transition-transform duration-200 ease-in-out">
      <div className="p-6 space-y-8">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold">Post Settings</h2>
          <Button variant="ghost" size="icon" onClick={onClose}>
            <X className="w-5 h-5" />
          </Button>
        </div>

        {/* Cover Image */}
        <div className="space-y-4">
          <Label>Cover Image</Label>
          <CoverImageUpload
            url={post.cover_image}
            onUpload={(url) => onUpdate({ cover_image: url })}
            onRemove={() => onUpdate({ cover_image: null })}
          />
        </div>

        {/* Slug */}
        <div className="space-y-2">
          <Label htmlFor="slug">URL Slug</Label>
          <Input
            id="slug"
            value={slug}
            onChange={(e) => {
              setSlug(e.target.value);
              onUpdate({ slug: e.target.value });
            }}
          />
          <p className="text-xs text-muted-foreground">
            syntactic.com/post/{slug}
          </p>
        </div>

        {/* Excerpt */}
        <div className="space-y-2">
          <Label htmlFor="excerpt">Excerpt</Label>
          <textarea
            id="excerpt"
            className="flex min-h-[80px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
            value={excerpt}
            onChange={(e) => {
              setExcerpt(e.target.value);
              onUpdate({ excerpt: e.target.value });
            }}
            placeholder="Brief description for SEO and previews..."
          />
        </div>

        {/* Series */}
        <div className="space-y-2">
          <Label>Series</Label>
          <div className="flex gap-2">
            <select
              className="flex h-10 w-full items-center justify-between rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
              value={post.series_id || ''}
              onChange={(e) => onUpdate({ series_id: e.target.value || null })}
            >
              <option value="">None</option>
              {series.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.title}
                </option>
              ))}
            </select>
            <Button
              variant="outline"
              size="icon"
              onClick={() => setIsCreatingSeries(true)}
              title="Create new series"
            >
              <Plus className="w-4 h-4" />
            </Button>
          </div>
          {isCreatingSeries && (
            <div className="flex gap-2 mt-2 items-center">
              <Input
                placeholder="New series name"
                value={newSeriesTitle}
                onChange={(e) => setNewSeriesTitle(e.target.value)}
                className="h-8"
              />
              <Button 
                size="sm" 
                onClick={handleCreateSeries}
                disabled={!newSeriesTitle.trim()}
              >
                Create
              </Button>
              <Button 
                variant="ghost" 
                size="sm" 
                onClick={() => setIsCreatingSeries(false)}
              >
                Cancel
              </Button>
            </div>
          )}
        </div>

        {/* Tags */}
        <div className="space-y-2">
          <Label>Tags</Label>
          <TagInput
            tags={post.tags || []}
            onChange={(tags) => onUpdate({ tags })}
          />
        </div>

        {/* Danger Zone */}
        <div className="pt-8 border-t">
          <Button 
            variant="destructive" 
            className="w-full"
            onClick={() => {
              if (confirm('Are you sure you want to delete this post?')) {
                // Handle delete
              }
            }}
          >
            Delete Post
          </Button>
        </div>
      </div>
    </div>
  );
}

