'use client';

import Editor, { OnMount, loader } from '@monaco-editor/react';
import { Language, languageInfo } from '@/lib/playground/templates';
import { Loader2 } from 'lucide-react';

interface CodeEditorProps {
  value: string;
  onChange: (value: string) => void;
  language: Language;
  theme: 'light' | 'dark';
  onRun: () => void;
}

export function CodeEditorWrapper({ value, onChange, language, theme, onRun }: CodeEditorProps) {

  const handleEditorMount: OnMount = (editor, monaco) => {
    // Define custom themes
    monaco.editor.defineTheme('syntactic-light', {
      base: 'vs',
      inherit: true,
      rules: [
        { token: 'keyword', foreground: 'CF222E', fontStyle: 'bold' },
        { token: 'string', foreground: '0A3069' },
        { token: 'number', foreground: '0550AE' },
        { token: 'function', foreground: '8250DF' },
        { token: 'comment', foreground: '6E7781', fontStyle: 'italic' },
        { token: 'operator', foreground: 'CF222E' },
        { token: 'type', foreground: '953800' },
      ],
      colors: {
        'editor.background': '#FFFFFF',
        'editor.foreground': '#24292F',
        'editor.lineHighlightBackground': '#F6F8FA',
        'editorLineNumber.foreground': '#57606A',
        'editorCursor.foreground': '#0969DA',
        'editor.selectionBackground': '#0969DA20',
      }
    });

    monaco.editor.defineTheme('syntactic-dark', {
      base: 'vs-dark',
      inherit: true,
      rules: [
        { token: 'keyword', foreground: 'FF7B72', fontStyle: 'bold' },
        { token: 'string', foreground: 'A5D6FF' },
        { token: 'number', foreground: '79C0FF' },
        { token: 'function', foreground: 'D2A8FF' },
        { token: 'comment', foreground: '8B949E', fontStyle: 'italic' },
        { token: 'operator', foreground: 'FF7B72' },
        { token: 'type', foreground: 'FFA657' },
      ],
      colors: {
        'editor.background': '#1E1E1E',
        'editor.foreground': '#E6EDF3',
        'editor.lineHighlightBackground': '#161B22',
        'editorLineNumber.foreground': '#6E7681',
        'editorCursor.foreground': '#58A6FF',
        'editor.selectionBackground': '#388BFD26',
      }
    });
    
    // Set theme
    monaco.editor.setTheme(theme === 'dark' ? 'syntactic-dark' : 'syntactic-light');

    // Keybinding for Run
    editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.Enter, () => {
      onRun();
    });
  };

  return (
    <div className="h-full w-full bg-white dark:bg-[#1E1E1E] transition-colors duration-200">
      <Editor
        height="100%"
        language={languageInfo[language].monacoLanguage}
        value={value}
        onChange={(value) => onChange(value || '')}
        onMount={handleEditorMount}
        theme={theme === 'dark' ? 'syntactic-dark' : 'syntactic-light'}
        loading={<div className="flex items-center justify-center h-full"><Loader2 className="animate-spin text-gray-400" /></div>}
        options={{
          minimap: { enabled: false },
          fontSize: 14,
          lineHeight: 22,
          fontFamily: "'Fira Code', 'JetBrains Mono', monospace",
          fontLigatures: true,
          lineNumbers: 'on',
          roundedSelection: false,
          scrollBeyondLastLine: false,
          automaticLayout: true,
          padding: { top: 16, bottom: 16 },
          cursorBlinking: 'smooth',
          cursorSmoothCaretAnimation: 'on',
          matchBrackets: 'always',
        }}
        className="font-mono"
      />
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Panel, PanelGroup } from 'react-resizable-panels';
import { PlaygroundNav } from '@/components/playground/playground-nav';
import { CodeEditorWrapper } from '@/components/playground/code-editor-wrapper';
import { OutputPanel } from '@/components/playground/output-panel';
import { StatusBar } from '@/components/playground/status-bar';
import { ResizeHandle } from '@/components/playground/resize-handle';
import { Language, templates } from '@/lib/playground/templates';
import { executeJavaScript } from '@/lib/playground/javascript-executor';

import { useMediaQuery } from '@/hooks/use-media-query';

export default function Playground() {
  const isMobile = useMediaQuery('(max-width: 768px)');
  const direction = isMobile ? 'vertical' : 'horizontal';

  // Theme state for EDITOR/OUTPUT ONLY. The UI generally stays light/neutral.
  const [editorTheme, setEditorTheme] = useState<'light' | 'dark'>('light');
  
  const [language, setLanguage] = useState<Language>('javascript');
  const [code, setCode] = useState(templates.javascript);
  const [output, setOutput] = useState('');
  const [error, setError] = useState<string | undefined>();
  const [isRunning, setIsRunning] = useState(false);

  const handleLanguageChange = (newLanguage: Language) => {
    setLanguage(newLanguage);
    setCode(templates[newLanguage]);
    handleClear();
  };

  const handleClear = () => {
    setOutput('');
    setError(undefined);
  };

  const handleRun = async () => {
    setIsRunning(true);
    handleClear();

    try {
      if (language === 'javascript') {
        const result = await executeJavaScript(code);
        setOutput(result.output);
        setError(result.error);
      } else {
        const response = await fetch('/api/playground/execute', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ code, language }),
        });
        const result = await response.json();
        if (!response.ok) throw new Error(result.error);
        setOutput(result.output);
        setError(result.error);
      }
    } catch (err: any) {
      setError(err.message || 'Execution failed');
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="h-full w-full flex flex-col bg-white overflow-hidden">
      {/* Navigation - Always Light/Neutral */}
      <PlaygroundNav 
        language={language}
        onLanguageChange={handleLanguageChange}
        onRun={handleRun}
        onSave={() => alert('Save functionality')}
        onReset={() => { setCode(templates[language]); handleClear(); }}
        onFiles={() => alert('File tree functionality')}
        isRunning={isRunning}
        theme={editorTheme}
        onThemeToggle={() => setEditorTheme(prev => prev === 'light' ? 'dark' : 'light')}
      />
      
      {/* Resizable Panels */}
      <div className="flex-1 overflow-hidden relative">
        <PanelGroup 
          direction={direction} 
          autoSaveId="playground-layout"
          key={direction} // Force re-render when direction changes to avoid layout bugs
        >
          {/* Editor Panel */}
          <Panel defaultSize={60} minSize={30} className={editorTheme === 'dark' ? 'bg-[#0D1117]' : 'bg-white'}>
            <CodeEditorWrapper 
              value={code}
              onChange={setCode}
              language={language}
              theme={editorTheme}
              onRun={handleRun}
            />
          </Panel>
          
          <ResizeHandle direction={direction} />
          
          {/* Output Panel */}
          <Panel 
            defaultSize={40} 
            minSize={20} 
            className={`
              ${editorTheme === 'dark' ? 'bg-[#0D1117]' : 'bg-[#F8F9FA]'}
              ${direction === 'horizontal' 
                ? (editorTheme === 'dark' ? 'border-l-2 border-[#30363D]' : 'border-l-2 border-[#E5E7EB]') 
                : (editorTheme === 'dark' ? 'border-t-2 border-[#30363D]' : 'border-t-2 border-[#E5E7EB]')
              }
            `}
          >
            <OutputPanel 
              output={output}
              error={error}
              onClear={handleClear}
              isRunning={isRunning}
            />
          </Panel>
        </PanelGroup>
      </div>
      
      {/* Status Bar */}
      <StatusBar 
        theme={editorTheme} 
        onThemeToggle={() => setEditorTheme(prev => prev === 'light' ? 'dark' : 'light')}
        isRunningLocally={language === 'javascript'} 
      />
    </div>
  );
}

interface StatusBarProps {
  theme: 'light' | 'dark';
  onThemeToggle: () => void;
  isRunningLocally?: boolean;
}

export function StatusBar({ theme, onThemeToggle, isRunningLocally = true }: StatusBarProps) {
  return (
    <div className="h-8 flex items-center justify-between px-4 border-t border-gray-200 bg-[#F9FAFB] transition-colors duration-200 select-none">
      <div className="flex items-center gap-4 text-xs text-gray-500">
        <div className="flex items-center gap-1.5">
          <kbd className="px-1.5 py-0.5 rounded border border-gray-300 bg-gray-100 font-sans text-[10px]">
            Ctrl
          </kbd>
          <span>+</span>
          <kbd className="px-1.5 py-0.5 rounded border border-gray-300 bg-gray-100 font-sans text-[10px]">
            Enter
          </kbd>
          <span className="ml-1">to run</span>
        </div>
        
        <span className="w-px h-3 bg-gray-300" />
        
        <span>{isRunningLocally ? 'Running locally' : 'Remote execution'}</span>
      </div>

      {/* Theme toggle removed from here as per request */}
      <div className="text-xs text-gray-400">
        Ready
      </div>
    </div>
  );
}

'use client';

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { usePathname } from 'next/navigation';

interface LoadingContextType {
  isLoading: boolean;
  setLoading: (loading: boolean) => void;
  loadingMessage?: string;
  setLoadingMessage: (message?: string) => void;
}

const LoadingContext = createContext<LoadingContextType | undefined>(undefined);

export function LoadingProvider({ children }: { children: ReactNode }) {
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState<string | undefined>();
  const pathname = usePathname();

  const setLoading = (loading: boolean) => {
    setIsLoading(loading);
    if (!loading) {
      setLoadingMessage(undefined);
    }
  };

  // Automatic Page Transition on Route Change
  useEffect(() => {
    // When path changes, we force loading to be true (if it wasn't already)
    // and then fade it out after a delay.
    setIsLoading(true);
    
    // Smooth transition out
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 500); // 500ms delay as requested

    return () => clearTimeout(timer);
  }, [pathname]);

  return (
    <LoadingContext.Provider value={{ isLoading, setLoading, loadingMessage, setLoadingMessage }}>
      {children}
      {/* Loading Overlay */}
      {isLoading && (
        <div className="fixed top-0 left-0 right-0 bottom-0 w-screen h-screen z-[99999] flex items-center justify-center bg-black/70 backdrop-blur-sm transition-all duration-300 animate-in fade-in">
          <div className="flex flex-col items-center gap-6 animate-in zoom-in-95 duration-500">
             {/* Cat Animation Container */}
            <div className="relative w-48 h-48 sm:w-64 sm:h-64 rounded-xl overflow-hidden shadow-[0_8px_32px_rgba(0,0,0,0.3)] border border-white/10 bg-white/5 backdrop-blur-sm">
              <img 
                src="/cat_ani.gif" 
                alt="Loading..." 
                className="w-full h-full object-cover"
              />
            </div>
            {/* Optional Loading Text if message is present, or default */}
            <p className="text-white text-lg font-medium tracking-wide animate-pulse">
              {loadingMessage || 'Loading...'}
            </p>
          </div>
        </div>
      )}
    </LoadingContext.Provider>
  );
}

export function useLoading() {
  const context = useContext(LoadingContext);
  if (context === undefined) {
    throw new Error('useLoading must be used within a LoadingProvider');
  }
  return context;
}

'use client';

import { Database, Table as TableIcon, Timer, AlertCircle } from 'lucide-react';

import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

interface ColumnSchema {
  name: string;
  type?: string;
}

interface TableSchema {
  name: string;
  columns: ColumnSchema[];
}

interface TableVisualizerProps {
  schema: TableSchema[];
  rows: Record<string, any>[];
  columns: string[];
  message?: string;
  executionTime?: number;
  error?: string | null;
}

export function TableVisualizer({ schema, rows, columns, message, executionTime, error }: TableVisualizerProps) {
  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <Card className="h-full">
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
          <div className="flex items-center gap-2">
            <Database className="w-4 h-4 text-blue-600 dark:text-blue-300" />
            <CardTitle className="text-base">Schema</CardTitle>
          </div>
        </CardHeader>
        <CardContent className="space-y-3">
          {schema.length === 0 && (
            <p className="text-sm text-slate-500 dark:text-slate-300">No tables yet. Run a CREATE TABLE statement to see it here.</p>
          )}
          {schema.map((table) => (
            <div key={table.name} className="rounded-md border border-slate-200 dark:border-slate-800 p-3">
              <div className="flex items-center gap-2 mb-2">
                <TableIcon className="w-4 h-4 text-slate-500" />
                <p className="font-semibold text-sm">{table.name}</p>
              </div>
              <div className="flex flex-wrap gap-2">
                {table.columns.map((col) => (
                  <Badge key={col.name} variant="secondary" className="text-xs">
                    {col.name}
                    {col.type ? ` (${col.type})` : ''}
                  </Badge>
                ))}
              </div>
            </div>
          ))}
        </CardContent>
      </Card>

      <Card className="h-full">
        <CardHeader className="space-y-2 pb-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <TableIcon className="w-4 h-4 text-emerald-600 dark:text-emerald-300" />
              <CardTitle className="text-base">Query Results</CardTitle>
            </div>
            {executionTime !== undefined && (
              <div className="inline-flex items-center gap-1 text-xs text-slate-500 dark:text-slate-300">
                <Timer className="w-3.5 h-3.5" />
                {executionTime} ms
              </div>
            )}
          </div>
          {message && <p className="text-xs text-slate-500 dark:text-slate-300">{message}</p>}
          {error && (
            <div className="inline-flex items-center gap-2 text-xs text-red-600 dark:text-red-400">
              <AlertCircle className="w-4 h-4" />
              <span>{error}</span>
            </div>
          )}
        </CardHeader>
        <CardContent className="overflow-auto">
          {!error && rows.length === 0 && !message && (
            <p className="text-sm text-slate-500 dark:text-slate-300">Run a SELECT query to see rows here.</p>
          )}
          {!error && rows.length === 0 && message && (
            <p className="text-sm text-slate-500 dark:text-slate-300">{message}</p>
          )}
          {!error && rows.length > 0 && (
            <div className="border border-slate-200 dark:border-slate-800 rounded-md overflow-auto">
              <table className="min-w-full text-sm">
                <thead className="bg-slate-100 dark:bg-slate-800/60">
                  <tr>
                    {columns.map((col) => (
                      <th key={col} className="text-left px-3 py-2 font-semibold text-slate-700 dark:text-slate-100 border-b border-slate-200 dark:border-slate-800">
                        {col}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row, idx) => (
                    <tr key={idx} className="odd:bg-white even:bg-slate-50 dark:odd:bg-slate-900 dark:even:bg-slate-800/60">
                      {columns.map((col) => (
                        <td key={col} className="px-3 py-2 border-b border-slate-200 dark:border-slate-800 align-top">
                          <span className="break-all">{formatCell(row[col])}</span>
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function formatCell(value: unknown) {
  if (value === null || value === undefined) return 'NULL';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}
